    Position position = new Position(getProtocolName());
    position.setDeviceId(deviceSession.getDeviceId());

    int index = buf.readerIndex();

    // Extended protocol header
    if (buf.getUnsignedMediumLE(index) == 0x7E020000) {

        index += 4;

        int type = buf.getUnsignedShortLE(index);

        index += 2;

        // Length of data block without header
        int dataLength = buf.getUnsignedShortLE(index);

        index += 2;

        if (type == 0x5501) {

            buf.skipBytes(6); // unknown
            position.set(Position.KEY_RESULT, readString(buf, 25));

            return position;

        }

        // BMS device
        else if (type == 0x5502) {

            buf.skipBytes(1); // subtype
            buf.skipBytes(6); // mac

            position.set("string", buf.readUnsignedByte() == 1);
            position.set("cover", buf.readUnsignedByte() == 1);
            position.set(Position.KEY_MOTION, buf.readUnsignedByte() == 1);

            //...

            return position;
        }
    }

    buf.readerIndex(index);

    // Standard protocol

    position.set(Position.KEY_ALARM, decodeAlarm(buf.readUnsignedInt()));

    decodeCoordinates(position, buf);

    position.setAltitude(buf.readShort());
    position.setSpeed(UnitsConverter.knotsFromKph(buf.readUnsignedShort() * 0.1));
    position.setCourse(buf.readUnsignedShort());
    position.setTime(readDate(buf, deviceSession.get(DeviceSession.KEY_TIMEZONE)));

    //...

    return position;
}
