            return null;
        }

        decodeFix(position, parser);
        decodeState(position, parser);

        if (type.equals("C")) {
            position.set(Position.KEY_HDOP, parser.nextDouble(3));
        } else if (type.equals("B") || type.equals("D")) {
            if (parser.nextInt(6)!= 0) { // Altitude value cannot be 0 for fix to be valid
                position.set(Position.KEYAltitude, parser.nextInt(6));
            }
        }

        return position;
    }

    return null;
}
