private void decodeCoordinates(Position position, ByteBuf buf) {
    int lat = buf.readInt();
    int lon = buf.readInt();

    if (lat!= 0 && lon!= 0) {
        position.setLatitude(lat / 1e7);
        position.setLongitude(lon / 1e7);
        position.setValid(true);
    } else {
        position.setValid(false);
    }
}

