                buf.skipBytes(2);
                int x = (buf.readUnsignedByte()<<8)|buf.readUnsignedByte();
                int y = (buf.readUnsignedByte()<<8)|buf.readUnsignedByte();
                int z = (buf.readUnsignedByte()<<8)|buf.readUnsignedByte();
